import json

def dedup_report(rows, key_fn):
    seen = {}
    unique = []
    conflicts = []
    for row in rows:
        key = key_fn(row)
        if key not in seen:
            seen[key] = row
            unique.append(row)
        elif seen[key] != row:
            conflicts.append({'key': key, 'kept': seen[key], 'other': row})
    return {'unique': unique, 'conflicts': conflicts}

def flatten_txs(clients):
    return [
        {'client_id': client['id'], 'tx_id': tx['id'], 'monto': tx['monto']}
        for client in clients
        for tx in client['txs']
    ]

def get_nested(d, *keys, default=None):
    cur = d
    for key in keys:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur

def export_deterministic(clients):
    ordered = sorted(clients, key=lambda client: client['id'])
    return json.dumps(ordered, sort_keys=True, ensure_ascii=False)
